<?php
require_once __DIR__.'/../includes/auth.php';$a=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);db()->prepare('UPDATE services SET is_active=1-is_active WHERE id=?')->execute([$id]);log_activity((int)$a['id'],'service_toggled','service',$id);redirect('admin/services.php');}
$pg=pagination_window(40,80);$q=db()->prepare('SELECT s.id,s.name,s.is_active,c.name category FROM services s JOIN categories c ON c.id=s.category_id ORDER BY c.name,s.name,s.id LIMIT '.($pg['per']+1).' OFFSET '.$pg['offset']);$q->execute();$rows=$q->fetchAll();$hasNext=trim_page_results($rows,$pg['per']);release_session_lock();$pageTitle='Services — Admin';require __DIR__.'/../includes/header.php';?>
<div class="container py-4"><?php include __DIR__.'/_nav.php';?><h1>Services</h1><div class="table-responsive"><table class="table"><tr><th>Service</th><th>Category</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['category'])?></td><td><?=$r['is_active']?'Active':'Disabled'?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary">Toggle</button></form></td></tr><?php endforeach;?></table></div><?=pagination_nav($pg['page'],$hasNext)?></div><?php require __DIR__.'/../includes/footer.php';?>
